#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "core/transport.h"
#include "core/usb_core.h"
#include "backends/hid_keyboard.c"
#include "fuzz/fuzz_wrap.h"

int main(int argc, char *argv[])
{
    const char *host = "127.0.0.1";
    const char *port = "4000";
    int sockfd;
    bool fuzz_mode = false;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--host") == 0 && i + 1 < argc) {
            host = argv[++i];
        } else if (strcmp(argv[i], "--port") == 0 && i + 1 < argc) {
            port = argv[++i];
        } else if (strcmp(argv[i], "--fuzz") == 0) {
            fuzz_mode = true;
        }
    }

    struct usb_device_ops *ops = &hid_keyboard_ops;

    if (fuzz_mode) {
        printf("[fuzz] Running in fuzz mode\n");
        struct usb_device_ops *wrapped = fuzz_wrap(ops);
        if (wrapped) {
            ops = wrapped;
        } else {
            fprintf(stderr, "[fuzz] Failed to create fuzz wrapper\n");
            return 1;
        }
    }

    sockfd = usbredir_connect(host, port);
    if (sockfd < 0) {
        fprintf(stderr, "Failed to connect to %s:%s\n", host, port);
        return 1;
    }

    usbredir_hello(sockfd, ops);
    usbredir_run(sockfd, ops);

    close(sockfd);
    return 0;
}
