/*
 * usb_yaml.c – YAML parser for USB description replay packets.
 *
 * Parses legacy pcap-replay YAML files (packet / USBpcap / USBpcapSetup / Raw)
 * into UsbYamlPacket structures for replaying captured USB traffic.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <yaml.h>
#include <glib.h>

#include "usb_yaml.h"
#include "log.h"

typedef enum {
    STATE_INITIAL,
    STATE_PACKET_LIST,
    STATE_PACKET_MAP,
    STATE_USBPCAP_MAP,
    STATE_USBPCAP_SETUP_MAP,
    STATE_RAW_MAP,
} ParseState;

/* ────────── UsbYamlPacket helpers ────────── */

UsbYamlPacket *usb_yaml_packet_new(void)
{
    UsbYamlPacket *pkt = g_new0(UsbYamlPacket, 1);
    return pkt;
}

void usb_yaml_packet_free(UsbYamlPacket *pkt)
{
    if (!pkt) return;
    g_free(pkt->raw_hex);
    g_free(pkt);
}

/* ────────── hex-string → binary ────────── */

static int hex_to_bytes(const char *hex, uint8_t *buf, size_t buf_len)
{
    size_t hex_len = strlen(hex);
    size_t n_bytes = hex_len / 2;

    if (hex_len % 2 != 0 || n_bytes > buf_len) return -1;

    for (size_t i = 0; i < n_bytes; i++) {
        unsigned int byte;
        if (sscanf(hex + 2*i, "%02x", &byte) != 1) return -1;
        buf[i] = (uint8_t)byte;
    }
    return (int)n_bytes;
}

/* ────────── YAML → packet list ────────── */

GList *usb_yaml_parse_file(const char *filename)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        usb_log(LOG_ERROR, "Cannot open YAML file: %s", filename);
        return NULL;
    }

    yaml_parser_t parser;
    yaml_event_t event;
    if (!yaml_parser_initialize(&parser)) {
        fclose(fp);
        return NULL;
    }
    yaml_parser_set_input_file(&parser, fp);

    GList *packets = NULL;
    UsbYamlPacket *current = NULL;
    ParseState state = STATE_INITIAL;
    char *current_key = NULL;

    while (1) {
        if (!yaml_parser_parse(&parser, &event)) {
            usb_log(LOG_ERROR, "YAML parse error at line %lu: %s",
                     parser.problem_mark.line + 1, parser.problem);
            break;
        }

        if (event.type == YAML_STREAM_END_EVENT) {
            yaml_event_delete(&event);
            break;
        }

        switch (event.type) {
        case YAML_SEQUENCE_START_EVENT:
            if (state == STATE_INITIAL)
                state = STATE_PACKET_LIST;
            break;

        case YAML_MAPPING_START_EVENT:
            switch (state) {
            case STATE_PACKET_LIST:
                current = usb_yaml_packet_new();
                state   = STATE_PACKET_MAP;
                break;
            default:
                break;
            }
            break;

        case YAML_MAPPING_END_EVENT:
            switch (state) {
            case STATE_RAW_MAP:
                state = STATE_PACKET_MAP;
                break;
            case STATE_USBPCAP_SETUP_MAP:
                state = STATE_USBPCAP_MAP;
                break;
            case STATE_USBPCAP_MAP:
                state = STATE_PACKET_MAP;
                break;
            case STATE_PACKET_MAP:
                if (current) {
                    packets = g_list_append(packets, current);
                    current = NULL;
                }
                state = STATE_PACKET_LIST;
                break;
            default:
                break;
            }
            break;

        case YAML_SCALAR_EVENT: {
            const char *val = (const char *)event.data.scalar.value;

            if (state == STATE_PACKET_MAP || state == STATE_USBPCAP_MAP ||
                state == STATE_USBPCAP_SETUP_MAP || state == STATE_RAW_MAP) {

                if (!current_key) {
                    /* This scalar is a key */
                    if (strcmp(val, "USBpcap") == 0)
                        state = STATE_USBPCAP_MAP;
                    else if (strcmp(val, "USBpcapSetup") == 0)
                        state = STATE_USBPCAP_SETUP_MAP;
                    else if (strcmp(val, "Raw") == 0)
                        state = STATE_RAW_MAP;
                    else
                        current_key = g_strdup(val);
                } else {
                    /* This scalar is a value */
                    if (!current) { g_free(current_key); current_key = NULL; break; }

                    if (state == STATE_USBPCAP_MAP) {
                        if (strcmp(current_key, "endpoint") == 0)
                            current->endpoint = (uint8_t)strtoul(val, NULL, 0);
                        else if (strcmp(current_key, "transfer") == 0)
                            current->transfer_type = (uint8_t)strtoul(val, NULL, 0);
                        else if (strcmp(current_key, "device") == 0)
                            current->device = (uint8_t)strtoul(val, NULL, 0);
                    } else if (state == STATE_USBPCAP_SETUP_MAP) {
                        if (strcmp(current_key, "bmRequestType") == 0)
                            current->bm_request_type = (uint8_t)strtoul(val, NULL, 0);
                        else if (strcmp(current_key, "bRequest") == 0)
                            current->b_request = (uint8_t)strtoul(val, NULL, 0);
                        else if (strcmp(current_key, "wValue") == 0)
                            current->w_value = (uint16_t)strtoul(val, NULL, 0);
                        else if (strcmp(current_key, "wIndex") == 0)
                            current->w_index = (uint16_t)strtoul(val, NULL, 0);
                        else if (strcmp(current_key, "wLength") == 0)
                            current->w_length = (uint16_t)strtoul(val, NULL, 0);
                    } else if (state == STATE_RAW_MAP) {
                        if (strcmp(current_key, "hex") == 0)
                            current->raw_hex = g_strdup(val);
                    } else if (state == STATE_PACKET_MAP) {
                        if (strcmp(current_key, "direction") == 0)
                            current->direction = (strcmp(val, "in") == 0) ? 1 : 0;
                    }

                    g_free(current_key);
                    current_key = NULL;
                }
            }
            break;
        }
        default:
            break;
        }

        yaml_event_delete(&event);
    }

    g_free(current_key);
    if (current) usb_yaml_packet_free(current);

    yaml_parser_delete(&parser);
    fclose(fp);
    return packets;
}

/* ────────── accessors ────────── */

int usb_yaml_packet_get_raw(UsbYamlPacket *pkt, uint8_t *buf, size_t buf_len)
{
    if (!pkt || !pkt->raw_hex) return -1;
    return hex_to_bytes(pkt->raw_hex, buf, buf_len);
}

int usb_yaml_packet_count(GList *packets)
{
    return (int)g_list_length(packets);
}

void usb_yaml_packet_list_free(GList *packets)
{
    g_list_free_full(packets, (GDestroyNotify)usb_yaml_packet_free);
}
```

