/*
 * usb_yaml.h – YAML parser for USB description replay packets.
 *
 * Legacy pcap-replay dialect: packet / USBpcap / USBpcapSetup / Raw.
 */

#ifndef USB_YAML_H
#define USB_YAML_H

#include <stdint.h>
#include <glib.h>

typedef struct {
    /* USBpcap header */
    uint8_t  endpoint;
    uint8_t  transfer_type;
    uint8_t  device;

    /* USBpcapSetup */
    uint8_t  bm_request_type;
    uint8_t  b_request;
    uint16_t w_value;
    uint16_t w_index;
    uint16_t w_length;

    /* Raw payload */
    char    *raw_hex;

    /* Packet direction (0 = out, 1 = in) */
    int      direction;
} UsbYamlPacket;

UsbYamlPacket *usb_yaml_packet_new(void);
void           usb_yaml_packet_free(UsbYamlPacket *pkt);

GList *usb_yaml_parse_file(const char *filename);
int    usb_yaml_packet_get_raw(UsbYamlPacket *pkt, uint8_t *buf, size_t buf_len);
int    usb_yaml_packet_count(GList *packets);
void   usb_yaml_packet_list_free(GList *packets);

#endif /* USB_YAML_H */
