#ifndef USB_PCAP_HDR_H
#define USB_PCAP_HDR_H

#include <stdint.h>

/*
 * USBPcap packet header — matches the layout in a pcap capture file.
 * Used by the pcap replay path.
 */
typedef struct __attribute__((packed)) {
    uint16_t header_len;
    uint64_t irp_id;
    uint32_t status;
    uint16_t function;
    uint8_t  info;
    uint16_t bus;
    uint16_t device;
    uint8_t  endpoint;
    uint8_t  transfer;
    uint32_t data_length;
} UsbPcapHeader;

/*
 * USB setup packet (8 bytes), embedded inside certain USBPcap frames.
 */
typedef struct __attribute__((packed)) {
    uint8_t  bmRequestType;
    uint8_t  bRequest;
    uint16_t wValue;
    uint16_t wIndex;
    uint16_t wLength;
} UsbSetupPacket;

#endif /* USB_PCAP_HDR_H */
