void hex_dump(const char *label, const uint8_t *data, size_t len)
{
    printf("%s (%zu bytes):\n", label, len);
    for (size_t i = 0; i < len; i++) {
        printf("%02x ", data[i]);
        if ((i + 1) % 16 == 0) printf("\n");
    }
    if (len % 16 != 0) printf("\n");
}

int parse_hex_string(const char *hex, uint8_t *buf, size_t buf_len)
{
    size_t hex_len = 0;
    while (hex[hex_len] && isxdigit((unsigned char)hex[hex_len]))
        hex_len++;

    size_t n_bytes = hex_len / 2;
    if (hex_len % 2 != 0 || n_bytes > buf_len) return -1;

    for (size_t i = 0; i < n_bytes; i++) {
        unsigned int byte;
        if (sscanf(hex + 2 * i, "%02x", &byte) != 1) return -1;
        buf[i] = (uint8_t)byte;
    }
    return (int)n_bytes;
}
