#include <stdio.h>
#include <string.h>
#include <time.h>

#include "record.h"
#include "log.h"

static FILE *record_fp = NULL;

int usb_record_start(const char *filename)
{
    record_fp = fopen(filename, "w");
    if (!record_fp) {
        usb_log(LOG_ERROR, "Cannot open record file: %s", filename);
        return -1;
    }
    usb_log(LOG_INFO, "Recording to %s", filename);
    return 0;
}

void usb_record_stop(void)
{
    if (record_fp) {
        fclose(record_fp);
        record_fp = NULL;
    }
}

void usb_record_packet(const char *direction, const uint8_t *data, size_t len)
{
    if (!record_fp) return;

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%H:%M:%S", tm);

    fprintf(record_fp, "[%s] %s (%zu bytes): ", ts, direction, len);
    for (size_t i = 0; i < len; i++)
        fprintf(record_fp, "%02x", data[i]);
    fprintf(record_fp, "\n");
    fflush(record_fp);
}
