#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>

#include "transport.h"
#include "../lib/log.h"

int usbredir_connect(const char *host, const char *port)
{
    struct addrinfo hints, *res, *rp;
    int sockfd;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int err = getaddrinfo(host, port, &hints, &res);
    if (err != 0) {
        usb_log(LOG_ERROR, "getaddrinfo: %s", gai_strerror(err));
        return -1;
    }

    for (rp = res; rp; rp = rp->ai_next) {
        sockfd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (sockfd < 0) continue;
        if (connect(sockfd, rp->ai_addr, rp->ai_addrlen) == 0) break;
        close(sockfd);
    }

    freeaddrinfo(res);

    if (!rp) {
        usb_log(LOG_ERROR, "Could not connect to %s:%s", host, port);
        return -1;
    }

    usb_log(LOG_INFO, "Connected to %s:%s (fd=%d)", host, port, sockfd);
    return sockfd;
}

int usbredir_send(int fd, const void *buf, size_t len)
{
    const uint8_t *p = buf;
    size_t remaining = len;

    while (remaining > 0) {
        ssize_t n = send(fd, p, remaining, 0);
        if (n <= 0) {
            usb_log(LOG_ERROR, "send() failed");
            return -1;
        }
        p += n;
        remaining -= n;
    }
    return 0;
}

int usbredir_recv(int fd, void *buf, size_t len)
{
    uint8_t *p = buf;
    size_t remaining = len;

    while (remaining > 0) {
        ssize_t n = recv(fd, p, remaining, 0);
        if (n <= 0) {
            if (n == 0) usb_log(LOG_INFO, "Connection closed by peer");
            else        usb_log(LOG_ERROR, "recv() failed");
            return -1;
        }
        p += n;
        remaining -= n;
    }
    return 0;
}
