#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "usb_core.h"
#include "transport.h"
#include "protocol.h"
#include "descriptor.h"
#include "../lib/log.h"
#include "../lib/utils.h"

/* ── hello handshake ── */

void usbredir_hello(int fd, struct usb_device_ops *ops)
{
    (void)ops;

    struct usbredir_hello hello;
    memset(&hello, 0, sizeof(hello));
    snprintf(hello.version, sizeof(hello.version), "usb-redir-emulator 0.1");

    hello.capabilities[0] =
        (1 << USBREDIR_CAP_CONNECT_DEVICE_VERSION) |
        (1 << USBREDIR_CAP_EP_INFO_MAX_PACKET_SIZE) |
        (1 << USBREDIR_CAP_64BIT_IDS) |
        (1 << USBREDIR_CAP_32BIT_BULK_LENGTH) |
        (1 << USBREDIR_CAP_BULK_RECEIVING);

    struct usbredir_header hdr = {
        .type   = USBREDIR_HELLO,
        .id     = 0,
        .length = sizeof(hello),
    };

    usbredir_send(fd, &hdr, sizeof(hdr));
    usbredir_send(fd, &hello, sizeof(hello));
    usb_log(LOG_INFO, "Sent hello (%zu bytes)", sizeof(hello));

    /* Receive peer hello */
    struct usbredir_header peer_hdr;
    if (usbredir_recv(fd, &peer_hdr, sizeof(peer_hdr)) < 0) return;

    uint8_t peer_data[256];
    if (peer_hdr.length > sizeof(peer_data)) {
        usb_log(LOG_ERROR, "Peer hello too large: %u", peer_hdr.length);
        return;
    }
    if (usbredir_recv(fd, peer_data, peer_hdr.length) < 0) return;

    struct usbredir_hello *peer = (struct usbredir_hello *)peer_data;
    usb_log(LOG_INFO, "Peer: %s  caps=0x%08x", peer->version, peer->capabilities[0]);
}

/* ── announce device ── */

static void send_device_connect(int fd, struct usb_device_ops *ops)
{
    struct usbredir_device_connect info;
    memset(&info, 0, sizeof(info));
    ops->get_device_info(ops, &info);

    struct usbredir_header hdr = {
        .type   = USBREDIR_DEVICE_CONNECT,
        .id     = 0,
        .length = sizeof(info),
    };
    usbredir_send(fd, &hdr, sizeof(hdr));
    usbredir_send(fd, &info, sizeof(info));
    usb_log(LOG_INFO, "Sent device_connect  vid=%04x pid=%04x",
            info.vendor_id, info.product_id);
}

static void send_interface_info(int fd, struct usb_device_ops *ops)
{
    uint8_t config_desc[512];
    int config_len = ops->get_descriptor(ops, 0x02, 0, config_desc, sizeof(config_desc));
    if (config_len < 0) {
        usb_log(LOG_ERROR, "Cannot get config descriptor");
        return;
    }

    struct usbredir_interface_info iinfo;
    desc_parse_interfaces(config_desc, config_len, &iinfo);

    struct usbredir_header hdr = {
        .type   = USBREDIR_INTERFACE_INFO,
        .id     = 0,
        .length = sizeof(iinfo),
    };
    usbredir_send(fd, &hdr, sizeof(hdr));
    usbredir_send(fd, &iinfo, sizeof(iinfo));
    usb_log(LOG_INFO, "Sent interface_info  count=%u", iinfo.interface_count);
}

static void send_ep_info(int fd, struct usb_device_ops *ops)
{
    uint8_t config_desc[512];
    int config_len = ops->get_descriptor(ops, 0x02, 0, config_desc, sizeof(config_desc));
    if (config_len < 0) return;

    struct usbredir_ep_info epinfo;
    desc_parse_endpoints(config_desc, config_len, &epinfo);

    struct usbredir_header hdr = {
        .type   = USBREDIR_EP_INFO,
        .id     = 0,
        .length = sizeof(epinfo),
    };
    usbredir_send(fd, &hdr, sizeof(hdr));
    usbredir_send(fd, &epinfo, sizeof(epinfo));
    usb_log(LOG_INFO, "Sent ep_info");
}

/* ── main dispatch loop ── */

void usbredir_run(int fd, struct usb_device_ops *ops)
{
    send_device_connect(fd, ops);
    send_interface_info(fd, ops);
    send_ep_info(fd, ops);

    usb_log(LOG_INFO, "Entering dispatch loop …");

    while (1) {
        struct usbredir_header hdr;
        if (usbredir_recv(fd, &hdr, sizeof(hdr)) < 0) break;

        uint8_t payload[4096];
        if (hdr.length > sizeof(payload)) {
            usb_log(LOG_ERROR, "Payload too large: %u", hdr.length);
            break;
        }
        if (hdr.length > 0) {
            if (usbredir_recv(fd, payload, hdr.length) < 0) break;
        }

        switch (hdr.type) {
        case USBREDIR_CONTROL_PACKET: {
            struct usbredir_control_packet *cp =
                (struct usbredir_control_packet *)payload;
            uint8_t *ctrl_data = payload + sizeof(*cp);
            uint16_t ctrl_data_len = hdr.length - sizeof(*cp);

            usb_log(LOG_DEBUG, "CONTROL  ep=%02x req=%02x val=%04x idx=%04x len=%u",
                    cp->endpoint, cp->request, cp->value, cp->index, cp->length);

            uint8_t response[512];
            int resp_len = ops->control(ops, cp, ctrl_data, ctrl_data_len,
                                         response, sizeof(response));
            if (resp_len < 0) resp_len = 0;

            struct usbredir_control_packet reply = *cp;
            reply.status = 0;
            reply.length = resp_len;

            struct usbredir_header rhdr = {
                .type   = USBREDIR_CONTROL_PACKET,
                .id     = hdr.id,
                .length = sizeof(reply) + resp_len,
            };
            usbredir_send(fd, &rhdr, sizeof(rhdr));
            usbredir_send(fd, &reply, sizeof(reply));
            if (resp_len > 0)
                usbredir_send(fd, response, resp_len);
            break;
        }

        case USBREDIR_BULK_PACKET: {
            struct usbredir_bulk_packet *bp =
                (struct usbredir_bulk_packet *)payload;
            usb_log(LOG_DEBUG, "BULK  ep=%02x", bp->endpoint);

            struct usbredir_bulk_packet reply = *bp;
            reply.status = 0;
            reply.length = 0;

            struct usbredir_header rhdr = {
                .type   = USBREDIR_BULK_PACKET,
                .id     = hdr.id,
                .length = sizeof(reply),
            };
            usbredir_send(fd, &rhdr, sizeof(rhdr));
            usbredir_send(fd, &reply, sizeof(reply));
            break;
        }

        case USBREDIR_INTERRUPT_PACKET: {
            struct usbredir_interrupt_packet *ip =
                (struct usbredir_interrupt_packet *)payload;
            uint8_t ep = ip->endpoint;

            /* IN endpoint — send HID report */
            if (ep & 0x80) {
                uint8_t report[64];
                int rlen = ops->ep_in(ops, ep, report, sizeof(report));
                if (rlen < 0) rlen = 0;

                struct usbredir_interrupt_packet reply;
                reply.endpoint = ep;
                reply.status   = 0;
                reply.length   = rlen;

                struct usbredir_header rhdr = {
                    .type   = USBREDIR_INTERRUPT_PACKET,
                    .id     = hdr.id,
                    .length = sizeof(reply) + rlen,
                };
                usbredir_send(fd, &rhdr, sizeof(rhdr));
                usbredir_send(fd, &reply, sizeof(reply));
                if (rlen > 0)
                    usbredir_send(fd, report, rlen);
            } else {
                /* OUT endpoint — e.g. LED update */
                uint8_t *out_data = payload + sizeof(*ip);
                uint16_t out_len = hdr.length - sizeof(*ip);
                if (ops->ep_out)
                    ops->ep_out(ops, ep, out_data, out_len);

                struct usbredir_interrupt_packet reply;
                reply.endpoint = ep;
                reply.status   = 0;
                reply.length   = 0;

                struct usbredir_header rhdr = {
                    .type   = USBREDIR_INTERRUPT_PACKET,
                    .id     = hdr.id,
                    .length = sizeof(reply),
                };
                usbredir_send(fd, &rhdr, sizeof(rhdr));
                usbredir_send(fd, &reply, sizeof(reply));
            }
            break;
        }

        default:
            usb_log(LOG_WARNING, "Unhandled message type %u", hdr.type);
            break;
        }
    }
}
