#include <string.h>
#include "descriptor.h"
#include "protocol.h"
#include "../lib/log.h"

/*
 * Walk a raw configuration descriptor blob and extract interface info.
 */
void desc_parse_interfaces(const uint8_t *config, int config_len,
                           struct usbredir_interface_info *info)
{
    memset(info, 0, sizeof(*info));

    int offset = 0;
    while (offset + 2 <= config_len) {
        uint8_t bLength = config[offset];
        uint8_t bDescType = config[offset + 1];

        if (bLength < 2 || offset + bLength > config_len) break;

        if (bDescType == 4 && bLength >= 9) {  /* INTERFACE descriptor */
            int idx = info->interface_count;
            if (idx >= 32) break;

            info->interface[idx]          = config[offset + 2]; /* bInterfaceNumber */
            info->interface_class[idx]    = config[offset + 5]; /* bInterfaceClass */
            info->interface_subclass[idx] = config[offset + 6]; /* bInterfaceSubClass */
            info->interface_protocol[idx] = config[offset + 7]; /* bInterfaceProtocol */
            info->interface_count++;
        }

        offset += bLength;
    }
}

/*
 * Walk a raw configuration descriptor blob and extract endpoint info.
 */
void desc_parse_endpoints(const uint8_t *config, int config_len,
                          struct usbredir_ep_info *info)
{
    memset(info, 0, sizeof(*info));

    /* Set all endpoint types to 255 = "not present" */
    memset(info->type, 0xff, sizeof(info->type));

    int offset = 0;
    int cur_interface = 0;

    while (offset + 2 <= config_len) {
        uint8_t bLength = config[offset];
        uint8_t bDescType = config[offset + 1];

        if (bLength < 2 || offset + bLength > config_len) break;

        if (bDescType == 4 && bLength >= 9) {  /* INTERFACE */
            cur_interface = config[offset + 2];
        }

        if (bDescType == 5 && bLength >= 7) {  /* ENDPOINT */
            uint8_t bEndpointAddress = config[offset + 2];
            uint8_t bmAttributes     = config[offset + 3];
            uint16_t wMaxPacketSize  = config[offset + 4] | (config[offset + 5] << 8);
            uint8_t bInterval        = config[offset + 6];

            /*
             * usbredir ep_info uses a flat 32-slot array:
             *   slots 0..15  → OUT endpoints 0..15
             *   slots 16..31 → IN  endpoints 0..15
             */
            int slot;
            if (bEndpointAddress & 0x80)
                slot = 16 + (bEndpointAddress & 0x0F);
            else
                slot = bEndpointAddress & 0x0F;

            if (slot < USBREDIR_MAX_ENDPOINTS) {
                info->type[slot]            = bmAttributes & 0x03;
                info->interval[slot]        = bInterval;
                info->interface[slot]       = cur_interface;
                info->max_packet_size[slot]  = wMaxPacketSize;
            }
        }

        offset += bLength;
    }
}
