static void kbd_get_device_info(struct usb_device_ops *ops,
                                 struct usbredir_device_connect *info)
{
    (void)ops;
    info->speed             = 1; /* full speed */
    info->device_class      = 0;
    info->device_subclass   = 0;
    info->device_protocol   = 0;
    info->vendor_id         = 0x04D9;
    info->product_id        = 0x1702;
    info->device_version_bcd = 0x0131;
}

static int kbd_get_descriptor(struct usb_device_ops *ops,
                               uint8_t desc_type, uint8_t desc_index,
                               uint8_t *buf, size_t buf_len)
{
    (void)ops;
    const uint8_t *src = NULL;
    size_t src_len = 0;

    switch (desc_type) {
    case 0x01:  /* DEVICE */
        src = device_desc; src_len = sizeof(device_desc); break;
    case 0x02:  /* CONFIGURATION */
        src = config_desc; src_len = sizeof(config_desc); break;
    case 0x22:  /* HID REPORT */
        src = hid_report_desc; src_len = sizeof(hid_report_desc); break;
    case 0x03:  /* STRING */
        switch (desc_index) {
        case 0: src = string_desc_langid; src_len = sizeof(string_desc_langid); break;
        case 1: src = string_desc_mfr;    src_len = sizeof(string_desc_mfr);    break;
        case 2: src = string_desc_prod;   src_len = sizeof(string_desc_prod);   break;
        default: return -1;
        }
        break;
    default:
        return -1;
    }

    if (src_len > buf_len) src_len = buf_len;
    memcpy(buf, src, src_len);
    return (int)src_len;
}

static int kbd_control(struct usb_device_ops *ops,
                        struct usbredir_control_packet *cp,
                        uint8_t *data, uint16_t data_len,
                        uint8_t *response, size_t response_len)
{
    (void)data;
    (void)data_len;

    uint8_t desc_type  = cp->value >> 8;
    uint8_t desc_index = cp->value & 0xFF;

    /* GET_DESCRIPTOR */
    if (cp->requesttype == 0x80 && cp->request == 6)
        return kbd_get_descriptor(ops, desc_type, desc_index, response, response_len);

    /* GET_DESCRIPTOR (interface — HID report) */
    if (cp->requesttype == 0x81 && cp->request == 6)
        return kbd_get_descriptor(ops, desc_type, desc_index, response, response_len);

    /* SET_CONFIGURATION — accept silently */
    if (cp->requesttype == 0x00 && cp->request == 9)
        return 0;

    /* SET_IDLE */
    if (cp->requesttype == 0x21 && cp->request == 0x0A)
        return 0;

    /* SET_PROTOCOL */
    if (cp->requesttype == 0x21 && cp->request == 0x0B)
        return 0;

    return -1;
}

static int kbd_ep_in(struct usb_device_ops *ops,
                      uint8_t endpoint,
                      uint8_t *buf, size_t buf_len)
{
    (void)ops;
    (void)endpoint;
    if (buf_len < 8) return -1;

    /* idle report — no keys pressed */
    memset(buf, 0, 8);
    return 8;
}

static void kbd_ep_out(struct usb_device_ops *ops,
                        uint8_t endpoint,
                        const uint8_t *data, uint16_t len)
