#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include "fuzz.h"
#include "../lib/log.h"

void fuzz_mutate(uint8_t *buf, size_t len, FuzzStrategy strategy)
{
    if (len == 0) return;

    switch (strategy) {
    case FUZZ_BITFLIP: {
        size_t pos = rand() % len;
        int bit = rand() % 8;
        buf[pos] ^= (1 << bit);
        break;
    }
    case FUZZ_RANDOM_BYTE: {
        size_t pos = rand() % len;
        buf[pos] = rand() & 0xFF;
        break;
    }
    case FUZZ_BOUNDARY: {
        size_t pos = rand() % len;
        uint8_t boundaries[] = { 0x00, 0x01, 0x7F, 0x80, 0xFE, 0xFF };
        buf[pos] = boundaries[rand() % 6];
        break;
    }
    case FUZZ_ZERO:
        memset(buf, 0, len);
        break;
    case FUZZ_MAX:
        memset(buf, 0xFF, len);
        break;
    }
}

void fuzz_init(void)
{
    srand((unsigned)time(NULL));
    usb_log(LOG_INFO, "Fuzzer initialized");
}
