typedef struct {
    struct usb_device_ops *inner;
} FuzzWrapPriv;

static void fuzz_get_device_info(struct usb_device_ops *ops,
                                  struct usbredir_device_connect *info)
{
    FuzzWrapPriv *p = ops->priv;
    p->inner->get_device_info(p->inner, info);
    fuzz_mutate((uint8_t *)info, sizeof(*info), FUZZ_RANDOM_BYTE);
}

static int fuzz_get_descriptor(struct usb_device_ops *ops,
                                uint8_t desc_type, uint8_t desc_index,
                                uint8_t *buf, size_t buf_len)
{
    FuzzWrapPriv *p = ops->priv;
    int len = p->inner->get_descriptor(p->inner, desc_type, desc_index, buf, buf_len);
    if (len > 0)
        fuzz_mutate(buf, len, FUZZ_BITFLIP);
    return len;
}

static int fuzz_control(struct usb_device_ops *ops,
                         struct usbredir_control_packet *cp,
                         uint8_t *data, uint16_t data_len,
                         uint8_t *response, size_t response_len)
{
    FuzzWrapPriv *p = ops->priv;
    int len = p->inner->control(p->inner, cp, data, data_len, response, response_len);
    if (len > 0)
        fuzz_mutate(response, len, FUZZ_BOUNDARY);
    return len;
}

static int fuzz_ep_in(struct usb_device_ops *ops, uint8_t endpoint,
                       uint8_t *buf, size_t buf_len)
{
    FuzzWrapPriv *p = ops->priv;
    int len = p->inner->ep_in(p->inner, endpoint, buf, buf_len);
    if (len > 0)
        fuzz_mutate(buf, len, FUZZ_RANDOM_BYTE);
    return len;
}

struct usb_device_ops *fuzz_wrap(struct usb_device_ops *inner)
{
    fuzz_init();

    FuzzWrapPriv *priv = calloc(1, sizeof(*priv));
    if (!priv) return NULL;
    priv->inner = inner;

    struct usb_device_ops *wrapped = calloc(1, sizeof(*wrapped));
    if (!wrapped) { free(priv); return NULL; }

    wrapped->name            = "fuzz_wrap";
    wrapped->priv            = priv;
    wrapped->get_device_info = fuzz_get_device_info;
    wrapped->get_descriptor  = fuzz_get_descriptor;
    wrapped->control         = fuzz_control;
    wrapped->ep_in           = fuzz_ep_in;
    wrapped->ep_out          = inner->ep_out;

    usb_log(LOG_INFO, "Fuzz wrapper created around '%s'", inner->name);
    return wrapped;
}
