#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "usb_pcap.h"
#include "../lib/log.h"

int usb_pcap_open(const char *filename, UsbPcapFile *pf)
{
    if (!filename || !pf) return -1;

    memset(pf, 0, sizeof(*pf));

    pf->fp = fopen(filename, "rb");
    if (!pf->fp) {
        usb_log(LOG_ERROR, "Cannot open pcap file: %s", filename);
        return -1;
    }

    /* Read global header (24 bytes) */
    uint8_t ghdr[24];
    if (fread(ghdr, 1, 24, pf->fp) != 24) {
        usb_log(LOG_ERROR, "Failed to read pcap global header");
        fclose(pf->fp);
        return -1;
    }

    uint32_t magic = *(uint32_t *)ghdr;
    if (magic == 0xA1B2C3D4) {
        pf->byte_swap = 0;
    } else if (magic == 0xD4C3B2A1) {
        pf->byte_swap = 1;
    } else {
        usb_log(LOG_ERROR, "Not a pcap file (bad magic: 0x%08x)", magic);
        fclose(pf->fp);
        return -1;
    }

    usb_log(LOG_INFO, "Opened pcap file: %s", filename);
    return 0;
}

int usb_pcap_read_packet(UsbPcapFile *pf, uint8_t *buf, size_t buf_len,
                          uint32_t *actual_len)
{
    if (!pf || !pf->fp) return -1;

    /* Packet header: ts_sec(4) ts_usec(4) incl_len(4) orig_len(4) */
    uint8_t phdr[16];
    if (fread(phdr, 1, 16, pf->fp) != 16) return -1;

    uint32_t incl_len = *(uint32_t *)(phdr + 8);
    if (pf->byte_swap) {
        incl_len = __builtin_bswap32(incl_len);
    }

    if (actual_len) *actual_len = incl_len;

    if (incl_len > buf_len) {
        /* Skip oversized packet */
        fseek(pf->fp, incl_len, SEEK_CUR);
        return -1;
    }

    if (fread(buf, 1, incl_len, pf->fp) != incl_len) return -1;

    pf->packet_count++;
    return 0;
}

void usb_pcap_close(UsbPcapFile *pf)
{
    if (pf && pf->fp) {
        fclose(pf->fp);
        pf->fp = NULL;
        usb_log(LOG_INFO, "Closed pcap file (%u packets read)", pf->packet_count);
    }
}
