/*
 * glib.c — USB descriptor tree model using GLib.
 *
 * Provides UsbNode (tree of named properties) where each property (UsbProp)
 * can hold a string, an integer, raw bytes, or a list of child UsbNodes.
 *
 * Usage: yaml_loader parses YAML into a UsbNode tree; yaml_backend serializes
 * the tree into binary USB descriptors.
 *
 * TODO:
 *   - Rename to usb_node.c and move into src/lib/.
 *   - Fix typedef names: adopt UsbNode / UsbProp consistently.
 *   - Add create_prop_u32() helper for integer properties.
 */

#include <glib.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ────────── Types ────────── */

typedef enum {
    USB_PROP_STRING,
    USB_PROP_INT,
    USB_PROP_BYTES,
    USB_PROP_CHILDREN,
} UsbPropType;

typedef struct _UsbProp UsbProp;
typedef struct _UsbNode UsbNode;

struct _UsbProp {
    char        *name;
    UsbPropType  type;
    union {
        char     *str_val;
        int       int_val;
        struct {
            uint8_t *data;
            size_t   length;
        } bytes;
        GList    *children;   /* list of UsbNode* */
    } value;
};

struct _UsbNode {
    char  *name;
    GList *props;  /* list of UsbProp* */
};

/* ────────── UsbProp constructors ────────── */

static UsbProp *create_prop_string(const char *name, const char *val)
{
    UsbProp *p = g_new0(UsbProp, 1);
    p->name = g_strdup(name);
    p->type = USB_PROP_STRING;
    p->value.str_val = g_strdup(val);
    return p;
}

static UsbProp *create_prop_int(const char *name, int val)
{
    UsbProp *p = g_new0(UsbProp, 1);
    p->name = g_strdup(name);
    p->type = USB_PROP_INT;
    p->value.int_val = val;
    return p;
}

static UsbProp *create_prop_bytes(const char *name, const uint8_t *data, size_t len)
{
    UsbProp *p = g_new0(UsbProp, 1);
    p->name = g_strdup(name);
    p->type = USB_PROP_BYTES;
    p->value.bytes.data = g_memdup2(data, len);
    p->value.bytes.length = len;
    return p;
}

static UsbProp *create_prop_children(const char *name)
{
    UsbProp *p = g_new0(UsbProp, 1);
    p->name = g_strdup(name);
    p->type = USB_PROP_CHILDREN;
    p->value.children = NULL;
    return p;
}

/* ────────── UsbNode helpers ────────── */

static UsbNode *usb_node_new(const char *name)
{
    UsbNode *n = g_new0(UsbNode, 1);
    n->name = g_strdup(name);
    n->props = NULL;
    return n;
}

static void usb_node_add_prop(UsbNode *node, UsbProp *prop)
{
    node->props = g_list_append(node->props, prop);
}

static UsbProp *usb_node_find_prop(UsbNode *node, const char *name)
{
    for (GList *l = node->props; l; l = l->next) {
        UsbProp *p = l->data;
        if (strcmp(p->name, name) == 0) return p;
    }
    return NULL;
}

/* ────────── free ────────── */

static void usb_prop_free(UsbProp *p);

static void usb_node_free(UsbNode *n)
{
    if (!n) return;
    g_free(n->name);
    g_list_free_full(n->props, (GDestroyNotify)usb_prop_free);
    g_free(n);
}

static void usb_prop_free(UsbProp *p)
{
    if (!p) return;
    g_free(p->name);
    switch (p->type) {
    case USB_PROP_STRING:
        g_free(p->value.str_val);
        break;
    case USB_PROP_BYTES:
        g_free(p->value.bytes.data);
        break;
    case USB_PROP_CHILDREN:
        g_list_free_full(p->value.children, (GDestroyNotify)usb_node_free);
        break;
    default:
        break;
    }
    g_free(p);
}

/* ────────── debug dump ────────── */

static void dump_node(UsbNode *node, int indent)
{
    if (!node) return;
    printf("%*s[%s]\n", indent, "", node->name);

    for (GList *l = node->props; l; l = l->next) {
        UsbProp *p = l->data;
        printf("%*s  %s: ", indent, "", p->name);
        switch (p->type) {
        case USB_PROP_STRING:
            printf("\"%s\"\n", p->value.str_val);
            break;
        case USB_PROP_INT:
            printf("%d (0x%X)\n", p->value.int_val, p->value.int_val);
            break;
        case USB_PROP_BYTES:
            printf("<%zu bytes>\n", p->value.bytes.length);
            break;
        case USB_PROP_CHILDREN:
            printf("(%u children)\n", g_list_length(p->value.children));
            for (GList *c = p->value.children; c; c = c->next)
                dump_node(c->data, indent + 4);
            break;
        }
    }
}

/* ────────── demo main ────────── */

int main(void)
{
    /* Build a small device-descriptor tree to prove the model works. */
    UsbNode *device = usb_node_new("device_descriptor");

    usb_node_add_prop(device, create_prop_int("bLength", 18));
    usb_node_add_prop(device, create_prop_int("bDescriptorType", 1));
    usb_node_add_prop(device, create_prop_int("bcdUSB", 0x0200));
    usb_node_add_prop(device, create_prop_int("idVendor", 0x04D9));
    usb_node_add_prop(device, create_prop_int("idProduct", 0x1702));
    usb_node_add_prop(device, create_prop_string("iManufacturer", "Holtek"));
    usb_node_add_prop(device, create_prop_string("iProduct", "USB Keyboard"));

    /* Nested: config → interface → endpoint */
    UsbNode *endpoint = usb_node_new("endpoint_descriptor");
    usb_node_add_prop(endpoint, create_prop_int("bEndpointAddress", 0x81));
    usb_node_add_prop(endpoint, create_prop_int("bmAttributes", 3));
    usb_node_add_prop(endpoint, create_prop_int("wMaxPacketSize", 8));

    UsbNode *iface = usb_node_new("interface_descriptor");
    usb_node_add_prop(iface, create_prop_int("bInterfaceClass", 3));
    UsbProp *ep_list = create_prop_children("endpoints");
    ep_list->value.children = g_list_append(ep_list->value.children, endpoint);
    usb_node_add_prop(iface, ep_list);

    UsbProp *if_list = create_prop_children("interfaces");
    if_list->value.children = g_list_append(if_list->value.children, iface);
    usb_node_add_prop(device, if_list);

    /* HID report descriptor as raw bytes */
    uint8_t hid_report[] = { 0x05,0x01, 0x09,0x06, 0xA1,0x01 };
    usb_node_add_prop(device, create_prop_bytes("hid_report", hid_report, sizeof(hid_report)));

    dump_node(device, 0);

    usb_node_free(device);
    return 0;
}
